// Plain-language note about how the roof pitch was detected (T003 smarter pitch).
const describePitchDetection = (analysis) => {
  if (analysis?.manual_pitch_override) {
    return analysis.area_recalibrated_from_footprint
      ? ' (✏️ manually set — area recalculated from 2D footprint)'
      : ' (✏️ manually set pitch)';
  }
  if (analysis?.photo_pitch_override) {
    return analysis.area_recalibrated_from_footprint
      ? ' (📷 photo-verified — area recalculated from 2D footprint)'
      : ' (📷 photo-verified pitch)';
  }
  if (!analysis?.pitch_confidence) return '';
  if (analysis.pitch_confidence === 'low') {
    return ' (assumed — satellite couldn\u2019t read the slope, please verify)';
  }
  const facets = Array.isArray(analysis.segment_pitches) ? analysis.segment_pitches : [];
  const distinct = [...new Set(facets.map(f => f.pitch))];
  if (facets.length >= 2 && distinct.length > 1) {
    return ` (averaged across ${facets.length} roof sections: ${distinct.slice(0, 4).join(', ')})`;
  }
  if (facets.length >= 2) {
    return ` (measured across ${facets.length} roof sections)`;
  }
  return ' (measured from 1 roof section)';
};
