function AddressConfirmMap({ pending, onConfirm, onCancel, googleMapsLoaded }) {
  const mapContainerRef = useRef(null);
  const confirmedCoordsRef = useRef({ ...pending.coordinates });

  useEffect(() => {
    const el = mapContainerRef.current;
    if (!el || !window.google) return;
    if (el.querySelector('.confirm-gmap')) return;

    const mapDiv = document.createElement('div');
    mapDiv.className = 'confirm-gmap';
    mapDiv.style.width = '100%';
    mapDiv.style.height = '340px';
    el.appendChild(mapDiv);

    const map = new window.google.maps.Map(mapDiv, {
      center: pending.coordinates,
      zoom: 20,
      mapTypeId: 'satellite',
      tilt: 0,
      heading: 0,
      disableDefaultUI: true,
      gestureHandling: 'greedy',
    });

    const marker = new window.google.maps.Marker({
      position: pending.coordinates,
      map,
      draggable: true,
      title: 'Drag to center of property',
      animation: window.google.maps.Animation.DROP,
    });

    marker.addListener('dragend', (e) => {
      confirmedCoordsRef.current = { lat: e.latLng.lat(), lng: e.latLng.lng() };
    });
  }, [googleMapsLoaded, pending.address]);

  return (
    <div className="space-y-3">
      <div className="relative rounded-xl border-2 border-green-400 shadow-lg overflow-hidden">
        <div ref={mapContainerRef} style={{ height: 340 }} />
        {/* Tooltip overlay — PG Reports style */}
        <div className="absolute top-4 right-4 bg-white rounded-xl shadow-xl border border-gray-200 px-5 py-4 z-20 min-w-[190px]">
          <p className="text-sm text-gray-700 font-medium mb-3 leading-snug">
            Drag the marker to the center of the address.
          </p>
          <button
            data-testid="button-confirm-satellite-address"
            className="w-full bg-green-600 hover:bg-green-700 active:bg-green-800 text-white font-bold text-base py-2 rounded-lg transition-colors"
            onClick={() => onConfirm({
              address: pending.address,
              coordinates: confirmedCoordsRef.current,
            })}
          >
            Confirm
          </button>
        </div>
        {/* Address label at bottom */}
        <div className="absolute bottom-3 left-3 bg-black/70 text-white text-xs px-3 py-1.5 rounded-lg font-medium max-w-[55%] truncate pointer-events-none">
          📍 {pending.address}
        </div>
      </div>
      <button
        className="w-full text-sm text-gray-500 hover:text-gray-700 py-1"
        onClick={onCancel}
      >
        ← Search a different address
      </button>
    </div>
  );
}

function SearchableEstimatorSelect({
  value,
  onChange,
  options = [],
  placeholder,
  searchPlaceholder = 'Search by name or address...',
  emptyText = 'No matches found.',
}) {
  const [open, setOpen] = useState(false);
  const [searchValue, setSearchValue] = useState('');

  const selectedOption = options.find((option) => String(option.value) === String(value));
  const normalizedSearch = searchValue.trim().toLowerCase();
  const filteredOptions = normalizedSearch
    ? options.filter((option) => String(option.searchText || option.label || '').toLowerCase().includes(normalizedSearch))
    : options;

  useEffect(() => {
    if (!open) setSearchValue('');
  }, [open]);

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          type="button"
          variant="outline"
          role="combobox"
          aria-expanded={open}
          className="w-full justify-between font-normal"
        >
          <span className={selectedOption ? 'truncate' : 'truncate text-muted-foreground'}>
            {selectedOption?.label || placeholder}
          </span>
          <ChevronDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-[--radix-popover-trigger-width] p-0" align="start">
        <Command shouldFilter={false}>
          <CommandInput
            value={searchValue}
            onValueChange={setSearchValue}
            placeholder={searchPlaceholder}
            aria-label={searchPlaceholder}
          />
          <CommandList>
            <CommandEmpty>{emptyText}</CommandEmpty>
            <CommandGroup>
              {filteredOptions.map((option) => (
                <CommandItem
                  key={String(option.value)}
                  value={String(option.value)}
                  onSelect={() => {
                    onChange(option.value);
                    setOpen(false);
                  }}
                >
                  <span className="truncate">{option.label}</span>
                  {String(option.value) === String(value) && (
                    <span className="ml-auto text-xs text-muted-foreground">Selected</span>
                  )}
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}

const SIDING_REPORT_EXTRACTION_PROMPT = `Extract the complete siding measurement model from this report.

IDENTITY — copy exactly from the printed report:
- report_provider: "HOVER" only when the document itself is HOVER-branded; otherwise the printed provider
- report_category: "complete_measurements" when it is a HOVER Complete Measurements report with siding tables, "siding" for a siding-only measurement report, or "roof" if no siding measurements exist
- property_id: the printed HOVER/property ID (never invent one)
- customer_info.property_address, city, state, and postal_code

SIDING MEASUREMENTS:
- siding facade area (the HOVER Areas > Siding > Facades value). HOVER says this area includes openings, so it is a pre-opening siding facade value — never call it net siding.
- gross_siding_facade_area_sqft: set this to that HOVER Facades value only when the report explicitly says it includes openings. Do not infer it from HOVER Total because Total can include trim.
- rough-opening quantity, area, and total perimeter from the Siding column
- every wall facade row, rough-opening assembly, and individual/mulled opening component available in the report
- net siding area only when the report explicitly prints a post-opening siding area before waste. HOVER Facades is NOT net siding. Do not infer it or substitute a waste-order quantity.
- trim area plus level starter, sloped trim, vertical trim, inside/outside corner lengths
- covered elevations and any missing/unknown photo coverage

Missing fields must be null or omitted, never zero. Preserve rough-opening assemblies separately from their individual components.`;

const SIDING_DOCUMENT_CLASSIFICATION_PROMPT = `Classify this document for estimate import.
Return document_type as "hover_measurement", "siding_measurement", "insurance_estimate", or "contractor_estimate".
Set has_siding_measurements true when it contains siding areas, Facades, rough openings, siding trim, or any siding table.

PRIORITY RULE — priced estimates always win:
- If the document has work line items with dollar amounts, a Rate/Unit Price column,
  RC/RCV/ACV/depreciation columns, a claim number, or an insurance carrier, classify
  it as "insurance_estimate" or "contractor_estimate" even if it includes a siding
  section or siding quantities.
- Use "siding_measurement" ONLY for a measurement-only report with no priced work
  line items and no claim/estimate financial columns.
- A HOVER Complete Measurements report with any siding table is
  "siding_measurement", not "hover_measurement".`;

